<?php require 'functions.php';$date=$_GET['date']??date('Y-m-d');$freights=array_values(array_filter(load_data('freights'),fn($x)=>$x['date']===$date));$products=load_data('products');$addresses=load_data('addresses');$carriers=load_data('carriers');if(isset($_GET['download'])){header('Content-Type:text/csv; charset=UTF-8');header('Content-Disposition: attachment; filename="fretes_'.$date.'.csv"');echo "\xEF\xBB\xBF";$out=fopen('php://output','w');fputcsv($out,['ID','Data','Origem','Destino','Transportador','Produtos','Status','Valor'],';');foreach($freights as $x){$o=find_by_id($addresses,$x['origin']);$d=find_by_id($addresses,$x['destination']);$c=find_by_id($carriers,$x['carrier']);$pn=[];foreach($x['products'] as $pid){$p=find_by_id($products,$pid);if($p)$pn[]=$p['name'];}fputcsv($out,[$x['id'],$x['date'],$o['label']??'',$d['label']??'',$c['name']??'',implode(', ',$pn),$x['status'],number_format($x['price'],2,',','')],';');}fclose($out);exit;}$title='Relatórios';require 'header.php';?>
<h2 class="page-title">Relatório diário de fretes</h2><div class="card p-4 mb-4"><form class="row g-3"><div class="col-md-6"><label class="form-label">Selecione a data</label><input type="date" class="form-control" name="date" value="<?=h($date)?>"></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-primary w-100">Consultar</button></div><div class="col-md-3 d-flex align-items-end"><a class="btn btn-success w-100" href="?date=<?=urlencode($date)?>&download=1">Baixar CSV</a></div></form></div><div class="card p-3"><p><strong><?=count($freights)?></strong> frete(s) em <?=date('d/m/Y',strtotime($date))?>.</p><div class="table-responsive"><table class="table"><thead><tr><th>ID</th><th>Transportador</th><th>Status</th><th>Valor</th></tr></thead><tbody><?php $total=0;foreach($freights as $x):$c=find_by_id($carriers,$x['carrier']);$total+=$x['price'];?><tr><td><?=$x['id']?></td><td><?=h($c['name']??'N/D')?></td><td><?=h($x['status'])?></td><td>R$ <?=number_format($x['price'],2,',','.')?></td></tr><?php endforeach;?></tbody><tfoot><tr><th colspan="3">Total</th><th>R$ <?=number_format($total,2,',','.')?></th></tr></tfoot></table></div></div><?php require 'footer.php';?>
